    keys = try c.decode([JSONValue].self, forKey: .keys)
    value = try c.decodeIfPresent(JSONValue.self, forKey: .value) ?? .null
    count = try c.decode(Int.self, forKey: .count)
    error = try c.decodeIfPresent(String.self, forKey: .error)
