    try c.encodeIfPresent(distribution, forKey: .distribution)
    try c.encodeIfPresent(nullCount, forKey: .nullCount)
    try c.encodeIfPresent(inputErrorCount, forKey: .inputErrorCount)
    try c.encode(keys, forKey: .keys)
    try c.encode(value, forKey: .value)
    try c.encode(count, forKey: .count)
    try c.encodeIfPresent(error, forKey: .error)
    try c.encodeIfPresent(y, forKey: .y)
    try c.encodeIfPresent(yError, forKey: .yError)
