    try c.encode(resolvedRevisions, forKey: .resolvedRevisions)
    try c.encode(fields, forKey: .fields)
    try c.encodeIfPresent(fingerprint, forKey: .fingerprint)
    try c.encodeIfPresent(snapshot, forKey: .snapshot)
